using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ExpandAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/Expand Action")]
public class ExpandAction : BattleAction
{
	public override void CastTargetAmount(GameObject corruptedAnimal, int amount, GameObject source)
	{
		corruptedAnimal.GetComponent<CorruptedAnimalCorruptionStats>().ModifyMaxOverCorruption(amount);
		ReferenceSingleton<GameStateManager>.Instance.SetChooseActionState();
	}
}
